from dataclasses import dataclass
@dataclass(frozen=True,slots=True)
class StatusDisplay:label:str;description:str;category:str;action:str
_LABELS={
'discovered':('Discovered','New marketing development identified.','neutral','Review coverage'),'qualification_pending':('Awaiting third publication','Coverage has not yet met the three-distinct-publication rule.','info','Review sources'),'qualified':('Qualified','Covered by at least three distinct approved publications.','success','Open case'),'rejected':('Rejected','The development does not currently meet qualification rules.','error','Review reasoning'),'research_pending':('Research queued','Research is waiting to begin.','neutral','Wait'),'researching':('Research in progress','Evidence is being assembled.','info','View progress'),'research_complete':('Research complete','The Evidence Pack is ready.','success','Review evidence'),'content_pending':('Content queued','The diagnosis is waiting to be drafted.','neutral','Wait'),'content_drafted':('Draft ready','Structured content is available.','info','Review draft'),'quality_review_pending':('Quality review in progress','Automated editorial checks are running.','info','View checks'),'quality_review_failed':('Needs revision','Blocking quality findings require attention.','error','Review findings'),'editorial_review_pending':('Ready for review','Quality checks passed; human review is required.','warning','Review content'),'revision_requested':('Revision requested','An editor requested changes.','warning','Revise content'),'approved':('Approved','Human editorial approval is complete.','success','Prepare publishing'),'publishing':('Publishing','The final document is being prepared.','info','View operation'),'published':('Published','The final document is available.','success','Plan distribution'),'email_pending':('Distribution in progress','Subscriber delivery is running.','info','View deliveries'),'emailed':('Distributed','Eligible subscribers were processed.','success','View summary'),'failed':('Action required','The workflow encountered a recoverable problem.','error','Review issue'),'archived':('Archived','This case is retained for history.','neutral','View history')}
def status_display(value):
 key=str(value or '').strip().lower();label,desc,cat,action=_LABELS.get(key,(key.replace('_',' ').title() or 'Unknown','Status details are unavailable.','neutral','Review'))
 return StatusDisplay(label,desc,cat,action)
def all_statuses():return dict(_LABELS)
